ruleExplore.coverUrl:
//span[@class="s2"]/a/@href
@js:
const cleanPath = result.replace(/^\/|\/$/g, "");

    // Extract the book ID
    const bookId = cleanPath.split("_")[1];

    // Extract the first five digits for the folder
    const folder = bookId.slice(0, 5);

    // Construct the new URL
    result = `http://www.qushucheng.com/images/${folder}/${bookId}/${bookId}s.jpg`;
